  function described(o) { const ids = [o.hint ? `${o.id}-hint` : null, o.error ? `${o.id}-error` : null, o.describedBy].filter(Boolean); return ids.length ? ` aria-describedby="${esc(ids.join(' '))}"` : ''; }
