  /** TN.ui.chipCheck({ id, name, value, label, checked, change }) -> pill checkbox (who takes part). */
  const chipCheck = (o = {}) => { const id = o.id || nextId('chip'); return `<label for="${esc(id)}" class="inline-flex min-h-10 cursor-pointer items-center gap-2 rounded-full border px-3 py-1.5 font-sans text-sm text-copy has-[:checked]:border-brand-strong has-[:checked]:bg-brand-tint has-[:checked]:font-semibold has-[:checked]:text-brand-deep border-control bg-card hover:border-quiet has-[:disabled]:cursor-not-allowed has-[:disabled]:opacity-70" data-slot="chip-check"><input id="${esc(id)}" type="checkbox" class="m-0 size-4 min-h-0 shrink-0 cursor-pointer accent-brand-strong ${FOCUS}"${o.name ? ` name="${esc(o.name)}"` : ''}${o.value != null ? ` value="${esc(o.value)}"` : ''}${o.checked ? ' checked=""' : ''}${o.change ? ` data-change="${esc(o.change)}"` : ''}/><span class="min-w-0 wrap-anywhere">${o.label}</span></label>`; };
